<?php
require_once __DIR__.'/config/database.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$q=$conn->prepare('SELECT * FROM quizzes WHERE id=?');$q->execute([$id]);$quiz=$q->fetch();if(!$quiz){http_response_code(404);exit('Quiz not found.');}$q=$conn->prepare('SELECT * FROM questions WHERE quiz_id=? ORDER BY sort_order,id');$q->execute([$id]);$questions=$q->fetchAll();$result=null;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$answers=$_POST['answer']??[];$score=0;foreach($questions as $item){if(strtolower((string)($answers[$item['id']]??''))===strtolower($item['answer']))$score++;}$save=$conn->prepare('INSERT INTO quiz_attempts(user_id,quiz_id,score,total) VALUES(?,?,?,?)');$save->execute([$_SESSION['user_id'],$id,$score,count($questions)]);$result=['score'=>$score,'answers'=>$answers];}$pageTitle=$quiz['title'];$activeNav='quizzes';require __DIR__.'/partials/header.php'; ?>
<section class="article-wrap"><a class="back-link" href="<?= e(app_url('quizzes.php')) ?>">← All quizzes</a><article class="article"><span class="eyebrow">KNOWLEDGE CHECK</span><h1><?= e($quiz['title']) ?></h1><p class="article-summary"><?= e($quiz['description']) ?></p><?php if($result): ?><div class="score-panel"><strong><?= $result['score'] ?>/<?= count($questions) ?></strong><span>Correct answers</span></div><?php endif; ?><form method="post" class="quiz-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php foreach($questions as $n=>$item): $key=strtolower($item['answer']); ?><fieldset class="question"><legend><b><?= $n+1 ?>.</b> <?= e($item['prompt']) ?></legend><?php foreach(['a','b','c','d'] as $letter): $val=$item['option_'.$letter];$right=$result && $key===$letter;$picked=$result && strtolower((string)($result['answers'][$item['id']]??''))===$letter; ?><label class="answer-option <?= $right?'correct-answer':'' ?> <?= $picked&&!$right?'wrong-answer':'' ?>"><input type="radio" name="answer[<?= (int)$item['id'] ?>]" value="<?= $letter ?>" <?= $picked?'checked':'' ?> <?= $result?'disabled':'' ?>><span><?= e($val) ?></span></label><?php endforeach; ?><?php if($result): ?><p class="explanation"><?= e($item['explanation']) ?></p><?php endif; ?></fieldset><?php endforeach; ?><?php if(!$result): ?><button class="button button-primary" type="submit">Submit answers <span>✓</span></button><?php else: ?><a class="button button-primary" href="<?= e(app_url('student/dashboard.php')) ?>">View my progress <span>↗</span></a><?php endif; ?></form></article></section><?php require __DIR__.'/partials/footer.php'; ?>
